contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: deposit to create a balance, minSum to set, collect amount to attempt
    function run(uint depositAmount, uint setMinSum, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);
        // ensure contract is configurable: set MinSum before Initialized
        c.SetMinSum(setMinSum); if (__ESBMC_reverted()) return;

        // make an initial deposit to have some balance (may be zero if depositAmount==0)
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // read values before Collect
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;

        // attempt Collect and observe revert
        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read values after Collect
        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;

        // Assert the general invariant: Collect never increases the caller's balance nor the contract's Ether balance.
        // If Collect reverted, both values must be unchanged. If it succeeded, both values must be <= their before-values.
        assert(
            (reverted && balAfter == balBefore && cBalAfter == cBalBefore)
            || (!reverted && balAfter <= balBefore && cBalAfter <= cBalBefore)
        );
    }

    receive() external payable { }
}

